cards.solution:
const BAWAAN = { tema: "terang", ukuran: 16 };
function bacaPengaturan(teks) {
  try {
    return { ...BAWAAN, ...JSON.parse(teks) };
  } catch (e) {
    return { ...BAWAAN };
  }
}
console.log(bacaPengaturan('{"tema":"gelap"}'));
console.log(bacaPengaturan("rusak{"));
console.log(bacaPengaturan('{"ukuran":18}').ukuran);
